require_once 'functions.php';require_admin();if(($_GET['download']??'')!=='sql'){page_header('Database Backup');?><h1>Database Backup</h1><section class="panel"><p>Download a SQL backup of the current SSDRS tables and data. Store the file securely.</p><a class="btn primary" href="backup.php?download=sql">Download SQL Backup</a></section><?php page_footer();exit;}
$tables=['users','students','violations','cases','reports','audit_logs'];$sql="-- SSDRS backup generated ".date('Y-m-d H:i:s')."\nSET FOREIGN_KEY_CHECKS=0;\nCREATE DATABASE IF NOT EXISTS ssdrs_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\nUSE ssdrs_db;\n\n";
foreach($tables as $t){$meta=$pdo->query("SHOW CREATE TABLE `$t`")->fetch();$sql.="DROP TABLE IF EXISTS `$t`;\n".$meta['Create Table'].";\n";$rows=$pdo->query("SELECT * FROM `$t`")->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $row){$cols=array_map(fn($c)=>'`'.str_replace('`','``',$c).'`',array_keys($row));$vals=[];foreach($row as $v)$vals[]=$v===null?'NULL':$pdo->quote((string)$v);$sql.="INSERT INTO `$t` (".implode(',',$cols).") VALUES (".implode(',',$vals).");\n";}$sql.="\n";}$sql.="SET FOREIGN_KEY_CHECKS=1;\n";log_action($pdo,'Downloaded SQL backup','Backup','Tables: '.implode(', ',$tables));header('Content-Type: application/sql; charset=utf-8');header('Content-Disposition: attachment; filename="ssdrs_backup_'.date('Ymd_His').'.sql"');echo $sql;exit;